import collections

def can_reach_one(m, n, max_iter=10000):
    S = {Fraction(m, n), Fraction(n, m)}
    elements = list(S)
    i = 0
    while i < len(elements):
        x = elements[i]
        for j in range(i + 1, len(elements)):
            y = elements[j]
            am = (x + y) / 2
            hm = (2 * x * y) / (x + y)
            if am == 1 or hm == 1:
                return True
            if am not in S:
                S.add(am)
                elements.append(am)
            if hm not in S:
                S.add(hm)
                elements.append(hm)
        i += 1
        if len(elements) > max_iter:
            return False
    return False

